import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class ContractTest{@Test void independentInputCopyEmptyDuplicatesAndNoRequiredNewSnapshotIdentity(){var first=new course.examples.objects.Book("One");var input=new ArrayList<>(List.of(first,first));Object owner=TaskBinding.owner(input);var view=TaskBinding.view(owner);var copy=TaskBinding.copy(owner);var snapshot=TaskBinding.snapshot(owner);input.clear();assertEquals(2,view.size());assertSame(first,view.get(0));assertSame(first,view.get(1));copy.add(new course.examples.objects.Book("Local"));copy.remove(0);assertEquals(2,copy.size());assertEquals(2,view.size());assertEquals(2,snapshot.size());TaskBinding.add(owner,new course.examples.objects.Book("New"));assertEquals(3,view.size());assertEquals(2,copy.size());assertEquals(2,snapshot.size());assertThrows(UnsupportedOperationException.class,()->view.remove(0));assertThrows(UnsupportedOperationException.class,()->snapshot.remove(0));first.borrow();assertThrows(IllegalStateException.class,()->first.borrow());assertTrue(first.borrowed());Object empty=TaskBinding.owner(new ArrayList<>());assertTrue(TaskBinding.view(empty).isEmpty());assertTrue(TaskBinding.copy(empty).isEmpty());assertTrue(TaskBinding.snapshot(empty).isEmpty());}}
